254	/** Freie Zusatzdaten einer Anfrage bereinigen (flach, begrenzt) */
255	function datenBereinigen(d, tiefe = 0) {
256	  if (!d || typeof d !== "object" || Array.isArray(d)) return {};
257	  const out = {};
258	  for (const [k, wert] of Object.entries(d).slice(0, 60)) {
259	    const key = String(k).replace(/[^\w.-]/g, "").slice(0, 60);
260	    if (!key || key === "__proto__" || key === "constructor" || key === "prototype") continue;
261	    if (typeof wert === "string") out[key] = v.mehrzeilig(wert, 2000);
262	    else if (typeof wert === "number" && Number.isFinite(wert)) out[key] = wert;
263	    else if (typeof wert === "boolean") out[key] = wert;
264	    else if (Array.isArray(wert)) out[key] = wert.slice(0, 30).map((x) => (typeof x === "number" || typeof x === "boolean" ? x : v.text(x, 200)));
265	    else if (wert && typeof wert === "object" && tiefe < 1) out[key] = datenBereinigen(wert, tiefe + 1);
266	  }
267	  return out;
268	}
