228	export async function crmKontakte(n, { q, rolle, tag: t, organisationId, zustaendigId, quelle, nurDubletten, limit = 500 } = {}) {
229	  rechtNoetig(n, "crm", 1);
230	  const db = await boLesen();
231	  let liste = db.bo.kontakte;
232	  if (rolle) liste = liste.filter((k) => k.rollen.includes(rolle));
233	  if (t) liste = liste.filter((k) => k.tags.some((x) => x.toLowerCase() === String(t).toLowerCase()));
234	  if (organisationId) liste = liste.filter((k) => k.organisationId === organisationId);
235	  if (zustaendigId) liste = liste.filter((k) => k.zustaendigId === zustaendigId);
236	  if (quelle) liste = liste.filter((k) => k.quelle === quelle);
237	  if (q) {
238	    const s = normText(q);
239	    const roh = String(q).toLowerCase();
240	    liste = liste.filter((k) => {
241	      const org = orgName(db)(k.organisationId);
242	      return normText([k.vorname, k.nachname, k.firma, org, k.ort, k.plz, (k.tags || []).join(" ")].join(" ")).includes(s) || (k.email || "").includes(roh) || k.id === String(q).toUpperCase() || (k.telefon || "").replace(/\D/g, "").includes(String(q).replace(/\D/g, "") || "#");
243	    });
244	  }
245	  const dubletten = new Set(dublettenFinden(db.bo.kontakte, { orgName: orgName(db) }).flatMap((p) => [p.a.id, p.b.id]));
246	  if (nurDubletten) liste = liste.filter((k) => dubletten.has(k.id));
247	  const alleTags = [...new Set(db.bo.kontakte.flatMap((k) => k.tags))].sort((a, b) => a.localeCompare(b, "de"));
248	  const eintraege = [...liste]
249	    .sort((a, b) => String(b.geaendertAm).localeCompare(String(a.geaendertAm)))
250	    .slice(0, Math.min(2000, Number(limit) || 500))
251	    .map((k) => kontaktListenEintrag(db, k, dubletten));
252	  return { kontakte: eintraege, gesamt: liste.length, tags: alleTags, dubletten: dubletten.size };
253	}
