271	/** Verlauf je Kontakt: CRM-Aktivitäten, Statuswechsel und Nachrichten der verknüpften Objekte, Protokoll */
272	function verlaufFuer(db, k, aktivitaeten) {
273	  const eintraege = aktivitaeten.map((a) => ({ am: a.am, art: "aktivitaet", typ: a.typ, titel: `${AKTIVITAET_TYPEN[a.typ] || a.typ}: ${a.betreff}`, text: a.text, von: a.von, link: a.bezugLink }));
274	  for (const b of k.bezuege || []) {
275	    const o = objektVon(db, b.art, b.id);
276	    if (!o) continue;
277	    const titel = objektTitel(db, b.art, o);
278	    for (const e of o.statusVerlauf || []) {
279	      eintraege.push({ am: e.am, art: "status", typ: b.art, titel: `${PROZESSE[b.art]?.label || b.art} „${titel}“: ${statusLabel(b.art, e.status)}`, text: e.kommentar || "", von: e.vonRolle === "system" ? "System" : nameVon(db, e.vonId) || (e.vonRolle === "eigentuemer" ? "Kontakt" : "Backoffice"), link: adminPfad(b.art, o) });
280	    }
281	    for (const m of db.nachrichten.filter((x) => x.bezugArt === b.art && x.bezugId === b.id && !x.system)) {
282	      eintraege.push({ am: m.am, art: "nachricht", typ: b.art, titel: `Nachricht im Thread „${titel}“`, text: m.text.slice(0, 240), von: m.vonAdmin ? nameVon(db, m.vonId) || "Backoffice" : nameVon(db, m.vonId) || "Eigentümer", link: adminPfad(b.art, o) });
283	    }
284	  }
285	  const ids = new Set((k.bezuege || []).map((b) => b.id));
286	  for (const a of db.aktivitaeten) {
287	    if (!ids.has(a.objektId) || ["status", "nachricht", "login"].includes(a.aktion)) continue;
288	    eintraege.push({ am: a.am, art: "protokoll", typ: a.aktion, titel: a.text, text: "", von: nameVon(db, a.nutzerId) || "System", link: null });
289	  }
290	  return eintraege.sort((a, b) => String(b.am).localeCompare(String(a.am))).slice(0, 300);
291	}
