// src/lib/plattform/server/passwort.js
//
// Passwort-Hashing für das Demo-Backend: scrypt mit 16 Byte Salt, Vergleich
// zeitkonstant. Format: scrypt$N$r$p$<salt b64>$<hash b64> (Parameter im Hash,
// damit sie später erhöht werden können). Frappe nutzt sein eigenes Verfahren.

import { randomBytes, scrypt, timingSafeEqual } from "node:crypto";

const N = 16384;
const R = 8;
const P = 1;
const LAENGE = 64;

function scryptAsync(passwort, salt, n, r, p) {
  return new Promise((resolve, reject) =>
    scrypt(passwort.normalize("NFKC"), salt, LAENGE, { N: n, r, p, maxmem: 64 * 1024 * 1024 }, (err, key) => (err ? reject(err) : resolve(key)))
  );
}

export async function passwortHash(passwort) {
  const salt = randomBytes(16);
  const key = await scryptAsync(String(passwort), salt, N, R, P);
  return `scrypt$${N}$${R}$${P}$${salt.toString("base64")}$${key.toString("base64")}`;
}

// Für unbekannte E-Mail-Adressen trotzdem rechnen – gleiche Antwortzeit (keine Konto-Enumeration)
let attrappe = null;

export async function passwortPruefen(passwort, gespeichert) {
  if (!gespeichert) {
    attrappe ||= await passwortHash("attrappe-ohne-konto");
    gespeichert = attrappe;
    passwort = `${passwort}-x`;
  }
  const teile = String(gespeichert).split("$");
  if (teile.length !== 6 || teile[0] !== "scrypt") return false;
  const [, n, r, p, salt, hash] = teile;
  const soll = Buffer.from(hash, "base64");
  const ist = await scryptAsync(String(passwort ?? ""), Buffer.from(salt, "base64"), Number(n), Number(r), Number(p));
  return soll.length === ist.length && timingSafeEqual(soll, ist);
}
// src/lib/plattform/server/rateLimit.js
//
// Einfaches Rate-Limit im Arbeitsspeicher (gleitendes Fenster je Schlüssel).
// Reicht für einen einzelnen Node-Prozess; bei mehreren Instanzen zusätzlich
// am Reverse-Proxy (nginx limit_req) begrenzen – siehe docs/PLATTFORM.md.

import { PlattformFehler } from "../fehler";

const speicher = (globalThis.__oiRateLimit ||= new Map());

/** Wirft 429, wenn `schluessel` mehr als `max` Treffer im Fenster hat */
export function rateLimit(schluessel, max, fensterMs) {
  const jetzt = Date.now();
  const liste = (speicher.get(schluessel) || []).filter((t) => jetzt - t < fensterMs);
  if (liste.length >= max) {
    speicher.set(schluessel, liste);
    throw new PlattformFehler(429, "Zu viele Versuche in kurzer Zeit – bitte warten Sie einige Minuten.");
  }
  liste.push(jetzt);
  speicher.set(schluessel, liste);

  // gelegentlich aufräumen
  if (speicher.size > 5000) {
    for (const [k, v] of speicher) if (!v.length || jetzt - v[v.length - 1] > 3600e3) speicher.delete(k);
  }
}

/** Grenzen je Aktion: [max, Fenster in ms] */
export const GRENZEN = {
  login: [10, 15 * 60e3],
  loginEmail: [8, 15 * 60e3],
  registrieren: [5, 60 * 60e3],
  anfrage: [10, 60 * 60e3],
  passwort: [5, 60 * 60e3],
  upload: [60, 60 * 60e3],
  nachricht: [120, 60 * 60e3],
  // Login, Sicherheit & Teams
  magicLink: [5, 60 * 60e3],
  zweiFaktor: [10, 15 * 60e3],
  einladung: [30, 60 * 60e3],
  export: [10, 60 * 60e3],
};

/**
 * In der Entwicklung sind die Grenzen 10-fach gelockert (wiederholte Testläufe),
 * über PLATTFORM_RATE_FAKTOR einstellbar. In Produktion gilt immer Faktor 1.
 */
export function grenze(name) {
  const [max, fenster] = GRENZEN[name];
  const faktor = process.env.NODE_ENV !== "production" ? Number(process.env.PLATTFORM_RATE_FAKTOR) || 10 : 1;
  return [Math.max(1, Math.round(max * faktor)), fenster];
}
// src/lib/plattform/server/leak.js
//
// Optionale Leak-Prüfung neuer Passwörter gegen „Have I Been Pwned“ (Pwned Passwords, k-Anonymity):
// Nur die ersten 5 Zeichen des SHA-1-Hashes verlassen den Server, der Abgleich des Rests erfolgt lokal.
// „Add-Padding“ verschleiert zusätzlich die Antwortgröße. Aktiv nur mit PLATTFORM_HIBP=1.
// Bei Netzfehlern/Zeitüberschreitung wird die Prüfung übersprungen (kein Ausfall der Registrierung).

import { createHash } from "node:crypto";
import { PlattformFehler } from "../fehler";

const URL_BASIS = "https://api.pwnedpasswords.com/range/";
const TIMEOUT_MS = 3000;

export const leakPruefungAktiv = () => process.env.PLATTFORM_HIBP === "1";

/** Anzahl der bekannten Vorkommen (0 = nicht bekannt) oder null, wenn nicht geprüft */
export async function passwortVorkommen(passwort) {
  if (!leakPruefungAktiv() || typeof passwort !== "string" || !passwort) return null;
  const sha1 = createHash("sha1").update(passwort, "utf8").digest("hex").toUpperCase();
  const praefix = sha1.slice(0, 5);
  const rest = sha1.slice(5);
  try {
    const res = await fetch(URL_BASIS + praefix, {
      headers: { "Add-Padding": "true", "User-Agent": "OekoInvest-Plattform" },
      cache: "no-store",
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    if (!res.ok) return null;
    const text = await res.text();
    for (const zeile of text.split(/\r?\n/)) {
      const [suffix, anzahl] = zeile.trim().split(":");
      if (suffix === rest) return Number(anzahl) || 0; // Padding-Zeilen haben Anzahl 0
    }
    return 0;
  } catch (e) {
    console.warn("[plattform] Leak-Prüfung übersprungen:", e?.name || "Fehler");
    return null;
  }
}

/** Wirft 422, wenn das Passwort in bekannten Datenlecks vorkommt (nur mit PLATTFORM_HIBP=1) */
export async function passwortLeakPruefen(passwort) {
  const n = await passwortVorkommen(passwort);
  if (n && n > 0) {
    throw new PlattformFehler(422, "Dieses Passwort ist aus bekannten Datenlecks bekannt und daher unsicher. Bitte wählen Sie ein anderes – am besten eine Passphrase aus mehreren Wörtern.", "passwort_geleakt");
  }
}
// src/lib/plattform/server/kycDatei.js
//
// KYC-Uploads: Typ an den ersten Bytes erkennen (nie dem Browser-MIME oder der Endung trauen) und Auslieferung
// einer entschlüsselten Unterlage (kein Cache, nosniff, Sandbox-CSP, kein Referrer).

export function mimeAusBytes(b) {
  if (b.length >= 5 && b[0] === 0x25 && b[1] === 0x50 && b[2] === 0x44 && b[3] === 0x46 && b[4] === 0x2d) return "application/pdf";
  if (b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return "image/jpeg";
  if (b.length >= 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 && b[4] === 0x0d && b[5] === 0x0a && b[6] === 0x1a && b[7] === 0x0a) return "image/png";
  return "";
}

export function kycDateiAntwort(meta, daten, { anzeigen = false } = {}) {
  const name = String(meta.name || "unterlage");
  const ascii = name.replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  return new Response(daten, {
    headers: {
      "Content-Type": meta.mime,
      "Content-Length": String(daten.length),
      "Content-Disposition": `${anzeigen ? "inline" : "attachment"}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(name)}`,
      "Cache-Control": "private, no-store, max-age=0",
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "no-referrer",
      "Content-Security-Policy": "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox",
    },
  });
}
// src/lib/plattform/server/kycKrypto.js
//
// Verschlüsselte Ablage der KYC-Unterlagen im Demo-Backend: AES-256-GCM (authentifiziert), je Datei zufälliger
// 96-Bit-IV, Dokument-ID als Zusatzdaten (AAD) – eine Datei lässt sich nicht unbemerkt einem anderen Dokument unterschieben.
//
// Schlüssel: PLATTFORM_KYC_SCHLUESSEL – 32 Byte als Hex (64 Zeichen) bzw. Base64, oder eine Passphrase ≥ 32 Zeichen
// (wird per scrypt abgeleitet). Erzeugen: `openssl rand -base64 32`. Ohne Schlüssel:
//   - Produktion: 503 (keine unverschlüsselte Ablage, kein stiller Fallback)
//   - Entwicklung: fester, UNSICHERER Entwicklungsschlüssel mit Warnung im Log
// Schlüsselwechsel: alte Dateien bleiben mit dem alten Schlüssel lesbar, wenn er in PLATTFORM_KYC_SCHLUESSEL_ALT steht
// (kommagetrennt). Die Schlüssel-Kennung (8 Byte SHA-256) steht im Dateikopf.
//
// Dateiformat: "OIKYC1" (6) | Schlüssel-Kennung (8) | IV (12) | Tag (16) | Chiffrat
// Frappe: privates File, zusätzlich AES-256-GCM mit site_config „oekoinvest_kyc_schluessel“ (plattform/kyc_kern.py).

import { createCipheriv, createDecipheriv, createHash, randomBytes, scryptSync } from "node:crypto";
import { PlattformFehler } from "../fehler";

const MAGIC = Buffer.from("OIKYC1", "ascii");
const DEV_PASSPHRASE = "oekoinvest-kyc-entwicklung-UNSICHER-nur-lokal-2026";
let gewarnt = false;

function schluesselAus(wert) {
  const s = String(wert || "").trim();
  if (!s) return null;
  if (/^[0-9a-f]{64}$/i.test(s)) return Buffer.from(s, "hex");
  if (/^[A-Za-z0-9+/_-]{43}=?$/.test(s)) {
    const b = Buffer.from(s.replace(/-/g, "+").replace(/_/g, "/"), "base64");
    if (b.length === 32) return b;
  }
  if (s.length < 32) throw new PlattformFehler(503, "Der Schlüssel für die KYC-Ablage ist zu kurz (mindestens 32 Zeichen).");
  return scryptSync(s, "oekoinvest-kyc-v1", 32);
}

const kennung = (k) => createHash("sha256").update(k).digest().subarray(0, 8);

export function kycSchluesselStatus() {
  const env = process.env.PLATTFORM_KYC_SCHLUESSEL;
  if (env) return { gesetzt: true, entwicklung: false };
  return { gesetzt: false, entwicklung: process.env.NODE_ENV !== "production" };
}

function aktuellerSchluessel() {
  const env = process.env.PLATTFORM_KYC_SCHLUESSEL;
  if (env) return schluesselAus(env);
  if (process.env.NODE_ENV === "production") {
    throw new PlattformFehler(503, "Die verschlüsselte Ablage für Verifizierungsunterlagen ist nicht eingerichtet (PLATTFORM_KYC_SCHLUESSEL).");
  }
  if (!gewarnt) {
    gewarnt = true;
    console.warn("[plattform-kyc] PLATTFORM_KYC_SCHLUESSEL fehlt – unsicherer Entwicklungsschlüssel aktiv (nur lokal verwenden).");
  }
  return scryptSync(DEV_PASSPHRASE, "oekoinvest-kyc-v1", 32);
}

function alleSchluessel() {
  const liste = [aktuellerSchluessel()];
  for (const alt of String(process.env.PLATTFORM_KYC_SCHLUESSEL_ALT || "").split(",")) if (alt.trim()) liste.push(schluesselAus(alt));
  if (process.env.PLATTFORM_KYC_SCHLUESSEL && process.env.NODE_ENV !== "production") liste.push(scryptSync(DEV_PASSPHRASE, "oekoinvest-kyc-v1", 32));
  return liste;
}

/** Klartext → verschlüsselter Puffer (aad = Dokument-ID) */
export function kycVerschluesseln(klartext, aad) {
  const k = aktuellerSchluessel();
  const iv = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", k, iv);
  c.setAAD(Buffer.from(String(aad), "utf8"));
  const chiffrat = Buffer.concat([c.update(klartext), c.final()]);
  return Buffer.concat([MAGIC, kennung(k), iv, c.getAuthTag(), chiffrat]);
}

/** Verschlüsselter Puffer → Klartext; Manipulation/falscher Schlüssel → Fehler */
export function kycEntschluesseln(daten, aad) {
  const b = Buffer.from(daten);
  if (b.length < 42 || !b.subarray(0, 6).equals(MAGIC)) throw new PlattformFehler(500, "Die Datei ist beschädigt.");
  const id = b.subarray(6, 14);
  const k = alleSchluessel().find((x) => kennung(x).equals(id));
  if (!k) throw new PlattformFehler(500, "Die Datei wurde mit einem unbekannten Schlüssel verschlüsselt.");
  const d = createDecipheriv("aes-256-gcm", k, b.subarray(14, 26));
  d.setAAD(Buffer.from(String(aad), "utf8"));
  d.setAuthTag(b.subarray(26, 42));
  try {
    return Buffer.concat([d.update(b.subarray(42)), d.final()]);
  } catch {
    throw new PlattformFehler(500, "Die Datei konnte nicht entschlüsselt werden (manipuliert oder falscher Schlüssel).");
  }
}

